struct Solution;

impl Solution {
    pub fn remove_nth_from_end(head: Option<Box<ListNode>>, n: i32) -> Option<Box<ListNode>> {
        let mut dummy = Box::new(ListNode { val: 0, next: head });
        let mut len = 0;
        let mut c = dummy.next.as_ref();
        while let Some(x) = c {
            len += 1;
            c = x.next.as_ref();
        }
        let mut cur = &mut dummy;
        for _ in 0..(len - n as usize) {
            cur = cur.next.as_mut().unwrap();
        }
        let removed = cur.next.take(); // the target node
        cur.next = removed.and_then(|r| r.next); // splice it out
        dummy.next
    }
}

