struct Solution;

impl Solution {
    pub fn diameter_of_binary_tree(root: &Option<Box<TreeNode>>) -> i32 {
        let mut best = 0;
        Self::height(root, &mut best);
        best
    }

    fn height(node: &Option<Box<TreeNode>>, best: &mut i32) -> i32 {
        match node {
            None => 0,
            Some(n) => {
                let (left, right) = (Self::height(&n.left, best), Self::height(&n.right, best));
                *best = (*best).max(left + right); // path bending at this node
                1 + left.max(right)
            }
        }
    }
}

