struct Solution;

impl Solution {
    pub fn is_balanced(root: &Option<Box<TreeNode>>) -> bool {
        Self::height(root) != -1
    }

    // returns the height, or -1 if the subtree is unbalanced
    fn height(node: &Option<Box<TreeNode>>) -> i32 {
        match node {
            None => 0,
            Some(n) => {
                let left = Self::height(&n.left);
                if left == -1 {
                    return -1;
                }
                let right = Self::height(&n.right);
                if right == -1 || (left - right).abs() > 1 {
                    return -1;
                }
                1 + left.max(right)
            }
        }
    }
}

