struct Solution;

impl Solution {
    pub fn permute(nums: Vec<i32>) -> Vec<Vec<i32>> {
        let mut res = Vec::new();
        Self::backtrack(&nums, &mut vec![false; nums.len()], &mut Vec::new(), &mut res);
        res
    }

    fn backtrack(nums: &[i32], used: &mut Vec<bool>, cur: &mut Vec<i32>, res: &mut Vec<Vec<i32>>) {
        if cur.len() == nums.len() {
            res.push(cur.clone());
            return;
        }
        for i in 0..nums.len() {
            if used[i] {
                continue;
            }
            used[i] = true;
            cur.push(nums[i]);
            Self::backtrack(nums, used, cur, res);
            cur.pop();
            used[i] = false;
        }
    }
}

