struct Solution;

impl Solution {
    pub fn solve(board: &mut Vec<Vec<char>>) {
        let (m, n) = (board.len(), board[0].len());
        for r in 0..m {
            Self::mark(board, r as i32, 0);
            Self::mark(board, r as i32, n as i32 - 1);
        }
        for c in 0..n {
            Self::mark(board, 0, c as i32);
            Self::mark(board, m as i32 - 1, c as i32);
        }
        for r in 0..m {
            for c in 0..n {
                if board[r][c] == 'O' {
                    board[r][c] = 'X'; // surrounded: capture
                } else if board[r][c] == 'T' {
                    board[r][c] = 'O'; // safe: restore
                }
            }
        }
    }

    fn mark(b: &mut Vec<Vec<char>>, r: i32, c: i32) {
        if r < 0 || c < 0 || r as usize >= b.len() || c as usize >= b[0].len() || b[r as usize][c as usize] != 'O' {
            return;
        }
        b[r as usize][c as usize] = 'T';
        Self::mark(b, r + 1, c);
        Self::mark(b, r - 1, c);
        Self::mark(b, r, c + 1);
        Self::mark(b, r, c - 1);
    }
}

